def binary_to_uint8(bytestring):
    py_bytes = list(bytestring[2:])

    if len(py_bytes) < 256:
        py_bytes.append(0)
    return py_bytes

def pir_to_encrypted_pair(elems):
    # print('elems type: ' + str(type(elems)))
    byte_tmp    = bytearray(elems)
    b_tmp       = bytearray(b'\x01\x01')
    
    byte_tmp01 = byte_tmp[:256]
    byte_tmp02 = byte_tmp[256:]

    if byte_tmp01[-1] == 0:
        byte_tmp01 = byte_tmp01[:-1]
    if byte_tmp02[-1] == 0:
        byte_tmp02 = byte_tmp02[:-1]

    byte_tmp01[0:0] = b_tmp
    byte_tmp02[0:0] = b_tmp

    c0 = gmpy2.from_binary(bytes(byte_tmp01))
    c1 = gmpy2.from_binary(bytes(byte_tmp02))
    
    return c0, c1

# Start main...
input_enc_pair = [mpz(), mpz()]

# Save encrypted pair to encrypted db
bin_tmp_01 = gmpy2.to_binary(input_enc_pair[0])
bin_tmp_02 = gmpy2.to_binary(input_enc_pair[1])
pir_c0 = binary_to_uint8(bin_tmp_01)
pir_c1 = binary_to_uint8(bin_tmp_02)

x = []
for ele0 in pir_c0:
	x.append(ele0)

for ele1 in pir_c1:
	x.append(ele1)
print(len(x))
c0, c1 = pir_to_encrypted_pair(x)
output_enc_pair = [c0, c1]

print('Input encrypted pair: ' + str(input_enc_pair))
print('Output encrypted pair: ' + str(output_enc_pair))
assert(input_enc_pair == output_enc_pair)
